  "lucky-streak": {"name": "Lucky Streak", "family": "Lucky Streak", "stage": 1, "section": "Hedonism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Hedonism", "level": 3, "not": false}]], "description": "Gains the ability to roll exploded die twice and pick the most extreme option."},
  "bookworm": {"name": "Bookworm", "family": "Bookworm", "stage": 1, "section": "Hedonism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Hedonism", "level": 3, "not": false}]], "description": "+1 XP for each book read. Learning a spell from the grimoire counts as a book."},
  "right-to-trial": {"name": "Right to Trial", "family": "Right to Trial", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 1, "not": false}]], "description": "Whenever they are about to kill a creature considered intelligent, they must grant it the right to a trial. If it truly agrees to follow the moral code, the character is prohibited from killing it, mutilating it, putting it in life-threatening situations, or allowing others to do so. Gains 2 XP each time they spare someone or a group of people."},
  "keeper-of-promises": {"name": "Keeper of Promises", "family": "Keeper of Promises", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 1, "not": false}]], "description": "Whenever they make a relevant promise and manage to fulfill it, they gain at least 1 XP. They can earn more for larger promises."},
  "honesty": {"name": "Honesty", "family": "Honesty", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 1, "not": false}]], "description": "Whenever the character or someone on their team is lying, make a Will test DL 5. If they succeed or crit, they must rectify the lie (this does not mean they are obliged to expose the truth). If they do not lie, regardless of passing the test, they gain 1 XP."},
  "steady-purpose": {"name": "Steady Purpose", "family": "Steady Purpose", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 2, "not": false}]], "description": "Gains the ability to make any test safely and preferring numbers closer to 6 instead of 5 if the test is in line to complete a promise."},
  "judge": {"name": "Judge", "family": "Judge", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 3, "not": false}]], "description": "Gains +2 in social actions whenever judging surrendered opponents. ★ Also gains +2 to mind altering spells against them."},
  "inspiring-rally": {"name": "Inspiring Rally", "family": "Inspiring Rally", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 4, "not": false}]], "description": "Rally adds the full +Charisma to the next morale test of the team."},
  "undaunted-oath": {"name": "Undaunted Oath", "family": "Undaunted Oath", "stage": 1, "section": "Providentialism", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Providentialism", "level": 5, "not": false}]], "description": "When the character is trying to fulfill a promise and receives a wound, they can immediately perform an action surge, even if they have no STA."},
  "cleric": {"name": "★ Cleric", "family": "★ Cleric", "stage": 1, "section": "Deities and Devotion", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Devotion", "level": 2, "not": false}]], "description": "The character becomes a cleric of a deity. It is only possible to become a cleric if the character is not devoted to another and shares a common conviction with the deity. This allows all abilities, spells and skills from the deity's list to be learned using Devotion as the talent."},
  "miracle": {"name": "★ Miracle", "family": "★ Miracle", "stage": 1, "section": "Deities and Devotion", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Devotion", "level": 3, "not": false}]], "description": "Allows asking a deity for a deal."},
