  "fear-of-heights": {"name": "Fear of Heights", "family": "Fear of Heights", "stage": 1, "section": "Traumas", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": -6, "talent": [], "requires": [], "requirements": [], "description": "Receives -5 for morale tests when in high places, with a risk of falling."},
