  "cypher": {"name": "Cypher", "family": "Cypher", "stage": 1, "section": "Linguistics", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Linguistics", "level": 2, "not": false}]], "description": "Codifies text with a cypher of DL vs 2x linguistics knowledge."},
  "decipher": {"name": "Decipher", "family": "Decipher", "stage": 1, "section": "Linguistics", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Linguistics", "level": 2, "not": false}]], "description": "Attempts to decipher unknown languages. Arbitrary DL vs 2x linguistics knowledge."},
  "forgery": {"name": "Forgery", "family": "Forgery", "stage": 1, "section": "Linguistics", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Linguistics", "level": 2, "not": false}]], "description": "Attempts to copy calligraphy and forge a written document. Skill use is Linguistics + Prestidigitation level (without proficiency)."},
  "identify-language": {"name": "Identify Language", "family": "Identify Language", "stage": 1, "section": "Linguistics", "usage": "passive", "activation": "passive", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Linguistics", "level": 0, "not": false}]], "description": "Attempts to identify an unknown language. DL vs 2x linguistics knowledge. Also may identify dialect and origin of the speaker."},
  "first-aid": {"name": "First Aid", "family": "First Aid", "stage": 1, "section": "Medicine", "usage": "full turn", "activation": "active", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Medicine", "level": 1, "not": false}]], "description": "Tries to stop bleeding through a tourniquet or pressure on self or other. Make a medicine test against a DL equal to 2x bleeding. On a hit or crit, prevents bleeding that turn completely. Reduces bleeding by 0/0/1/2."},
  "cauterization": {"name": "Cauterization", "family": "Cauterization", "stage": 1, "section": "Medicine", "usage": "4 AP", "activation": "active", "cost": {"AP": 4, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Medicine", "level": 1, "not": false}]], "description": "Requires a focus surge. Tries to stop bleeding through burning the area. Causes 10 fire damage that ignores armor and reduces bleeding by 2."},
  "bone-setting": {"name": "Bone Setting", "family": "Bone Setting", "stage": 1, "section": "Medicine", "usage": "1 ET", "activation": "active", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 1}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Medicine", "level": 1, "not": false}], [{"kind": "gear", "name": "Splint", "not": false}]], "description": "In one ET, make a medicine test DL 3 to allow a wound to heal with rest. It heals 0/1/2/2 per sleep. A crit does not spend the ET. The test only needs to be done once per wound. The patient is considered to be resting or sleeping."},
  "wound-triage": {"name": "Wound Triage", "family": "Wound Triage", "stage": 1, "section": "Medicine", "usage": "1 ET", "activation": "active", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 1}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Medicine", "level": 1, "not": false}], [{"kind": "gear", "name": "Bandages", "not": false}]], "description": "In one ET, make a medicine test to prevent infection. It lowers the DL of the infection test by 2. One test can be used for the whole team and can be retried, but spends resources per character per attempt. The patient is considered to be resting or sleeping."},
  "diagnosis": {"name": "Diagnosis", "family": "Diagnosis", "stage": 1, "section": "Medicine", "usage": "0 AP", "activation": "active", "cost": {"AP": 0, "STA": 0, "exhaustion": 0, "IL": 0, "ET": 0}, "XPcost": 0, "karma": 0, "talent": [], "requires": [], "requirements": [[{"kind": "trainable", "name": "Medicine", "level": 1, "not": false}]], "description": "Make a medicine test of an arbitrary DL to diagnose a disease or poisoning. On a hit or crit, the character knows what the disease and treatment are."},
